import msgpack,struct,zlib,json
b=open('inputs/chall/unknown.data','rb').read()
# Recursively expose schema and contact/name values only; suppress all other data values (especially key material).
def summary(v,path='root',depth=0):
 if depth>10:return {'type':type(v).__name__,'depth_cap':True}
 if isinstance(v,dict):
  return {'type':'map','n':len(v),'entries':[{'key':str(k)[:100],'value':summary(x,path+'/'+str(k),depth+1)} for k,x in list(v.items())[:100]]}
 if isinstance(v,(list,tuple)):
  return {'type':type(v).__name__,'n':len(v),'items':[summary(x,path+'[]',depth+1) for x in v[:100]]}
 if isinstance(v,(bytes,bytearray)):
  return {'type':'bytes','n':len(v)}
 if isinstance(v,str):
  low=path.lower()
  if any(w in low for w in ('private','secret','password','token','key','email','credential')):
   return {'type':'str','n':len(v),'value':'[suppressed]'}
  if any(w in low for w in ('contact','name','person','display')):
   return {'type':'str','n':len(v),'value':v[:160]}
  return {'type':'str','n':len(v),'value':'[suppressed]'}
 if v is None or isinstance(v,(bool,int,float)):
  return {'type':type(v).__name__,'value':v if not isinstance(v,float) or abs(v)<1e100 else '[float]'}
 return {'type':type(v).__name__}
try:
 x=msgpack.unpackb(b,raw=False,strict_map_key=False)
 print('msgpack_valid yes')
 print(json.dumps(summary(x),ensure_ascii=True))
except Exception as e: print('msgpack_valid no',type(e).__name__,str(e))
# Locate complete gzip headers (not only the two-byte prefix) and validate each stream.
pos=[]; at=0
while True:
 at=b.find(b'\x1f\x8b\x08',at)
 if at<0:break
 pos.append(at); at+=1
print('complete_gzip_header_offsets',pos)
for off in (18272,19082):
 print('two_byte_marker',off,'header_bytes',b[off:off+10].hex())
 if b[off:off+3]==b'\x1f\x8b\x08':
  try:
   d=zlib.decompressobj(31); out=d.decompress(b[off:],1000000)
   print('gzip_valid',off,'eof',d.eof,'uncompressed_length',len(out),'format',('sqlite' if out.startswith(b'SQLite format 3\x00') else 'zip' if out.startswith(b'PK\x03\x04') else 'other'))
  except Exception as e: print('gzip_error',off,type(e).__name__,str(e))
